    13→namespace Nethermind.Evm.State;
    14→
    15→/// <summary>
    16→/// Represents state that can be anchored at specific state root, snapshot, committed, reverted.
    17→/// <see cref="BeginScope"/> must be called before any other operation, or it will throw. The returned <see cref="IDisposable"/>
    18→/// must be disposed to close the <see cref="IWorldState"/>. Multiple block can be executed or saved within the same scope.
    19→/// </summary>
    20→public interface IWorldState : IJournal<Snapshot>, IReadOnlyStateProvider
    21→{
    22→    // For scope to create genesis.
    23→    const BlockHeader? PreGenesis = null;
    24→
    25→    IDisposable BeginScope(BlockHeader? baseBlock);
    26→    bool IsInScope { get; }
    27→    new ref readonly UInt256 GetBalance(Address address);
    28→    new ref readonly ValueHash256 GetCodeHash(Address address);
    29→    bool HasStateForBlock(BlockHeader? baseBlock);
    30→
    31→    /// <summary>
    32→    /// Return the original persistent storage value from the storage cell
    33→    /// </summary>
    34→    /// <param name="storageCell"></param>
    35→    /// <returns></returns>
    36→    byte[] GetOriginal(in StorageCell storageCell);
    37→
    38→    /// <summary>
    39→    /// Get the persistent storage value at the specified storage cell
    40→    /// </summary>
    41→    /// <param name="storageCell">Storage location</param>
    42→    /// <returns>Value at cell</returns>
    43→    ReadOnlySpan<byte> Get(in StorageCell storageCell);
    44→
    45→    /// <summary>
    46→    /// Set the provided value to persistent storage at the specified storage cell
    47→    /// </summary>
    48→    /// <param name="storageCell">Storage location</param>
    49→    /// <param name="newValue">Value to store</param>
    50→    void Set(in StorageCell storageCell, byte[] newValue);
    51→
    52→    /// <summary>
    53→    /// Get the transient storage value at the specified storage cell
    54→    /// </summary>
    55→    /// <param name="storageCell">Storage location</param>
    56→    /// <returns>Value at cell</returns>
    57→    ReadOnlySpan<byte> GetTransientState(in StorageCell storageCell);
    58→
    59→    /// <summary>
    60→    /// Set the provided value to transient storage at the specified storage cell
    61→    /// </summary>
    62→    /// <param name="storageCell">Storage location</param>
    63→    /// <param name="newValue">Value to store</param>
    64→    void SetTransientState(in StorageCell storageCell, byte[] newValue);
    65→
    66→    /// <summary>
    67→    /// Reset all storage
    68→    /// </summary>
    69→    void Reset(bool resetBlockChanges = true);
    70→
    71→    /// <summary>
    72→    /// Creates a restartable snapshot.
    73→    /// </summary>
    74→    /// <param name="newTransactionStart"> Indicates new transaction will start here.</param>
    75→    /// <returns>Snapshot index</returns>
    76→    /// <remarks>
    77→    /// If <see cref="newTransactionStart"/> is true and there are already changes in <see cref="IStorageProvider"/> then next call to
    78→    /// <see cref="GetOriginal"/> will use changes before this snapshot as original values for this new transaction.
    79→    /// </remarks>
    80→    Snapshot TakeSnapshot(bool newTransactionStart = false);
    81→
    82→    Snapshot IJournal<Snapshot>.TakeSnapshot() => TakeSnapshot();
    83→
    84→    void WarmUp(AccessList? accessList);
    85→
    86→    void WarmUp(Address address);
    87→
    88→    /// <summary>
    89→    /// Clear all storage at specified address
    90→    /// </summary>
    91→    /// <param name="address">Contract address</param>
    92→    void ClearStorage(Address address);
    93→
    94→    void RecalculateStateRoot();
    95→
    96→    void DeleteAccount(Address address);
    97→
    98→    void CreateAccount(Address address, in UInt256 balance, in UInt256 nonce = default);
    99→    void CreateAccountIfNotExists(Address address, in UInt256 balance, in UInt256 nonce = default);
   100→
   101→    /// <summary>
   102→    /// Inserts the given smart contract code into the system at the specified address,
   103→    /// associating it with a unique code hash.
   104→    /// </summary>
   105→    /// <param name="address">The target address where the code is to be inserted.</param>
   106→    /// <param name="codeHash">The hash representing the code content, used for deduplication and reference.</param>
   107→    /// <param name="code">The bytecode to be inserted.</param>
   108→    /// <param name="spec">The current release specification which may affect validation or processing rules.</param>
   109→    /// <param name="isGenesis">Indicates whether the insertion is part of the genesis block setup.</param>
   110→    /// <returns>True if the code was inserted to the database at that hash; otherwise false if it was already there.
   111→    /// Note: This is different from whether the account has its hash updated</returns>
   112→    bool InsertCode(Address address, in ValueHash256 codeHash, ReadOnlyMemory<byte> code, IReleaseSpec spec, bool isGenesis = false);
   113→
   114→    void AddToBalance(Address address, in UInt256 balanceChange, IReleaseSpec spec);
   115→
   116→    bool AddToBalanceAndCreateIfNotExists(Address address, in UInt256 balanceChange, IReleaseSpec spec);
   117→
   118→    void SubtractFromBalance(Address address, in UInt256 balanceChange, IReleaseSpec spec);
   119→
   120→    void IncrementNonce(Address address, UInt256 delta);
   121→
   122→    void DecrementNonce(Address address, UInt256 delta);
   123→
   124→    void IncrementNonce(Address address) => IncrementNonce(address, UInt256.One);
   125→
   126→    void DecrementNonce(Address address) => DecrementNonce(address, UInt256.One);
   127→
   128→    void SetNonce(Address address, in UInt256 nonce);
   129→
   130→    /* snapshots */
   131→
